import{_ as e,o as a,c as r,a3 as n}from"./chunks/framework.BFeCKmyl.js";const u=JSON.parse('{"title":"Inserir trecho do documento no memo","description":"","frontmatter":{"title":"Inserir trecho do documento no memo","id":"eproc-memo-trecho-documento","plataforma":"eproc","grupo":"Eventos","plano":"free","desde":"1.13.0","padrao":"ligado","head":[["link",{"rel":"canonical","href":"https://eploc.com.br/manual/funcionalidades/eproc-memo-trecho-documento"}],["meta",{"property":"og:url","content":"https://eploc.com.br/manual/funcionalidades/eproc-memo-trecho-documento"}],["meta",{"property":"og:title","content":"Inserir trecho do documento no memo | Manual do eploc"}],["meta",{"property":"og:description","content":"Manual oficial do eploc, extensão para Chrome e Edge que acelera o trabalho no eproc, SEI e RUPE."}]]},"headers":[],"relativePath":"funcionalidades/eproc-memo-trecho-documento.md","filePath":"funcionalidades/eproc-memo-trecho-documento.md"}'),t={name:"funcionalidades/eproc-memo-trecho-documento.md"};function i(c,o,s,d,m,l){return a(),r("div",null,o[0]||(o[0]=[n('<h1 id="inserir-trecho-do-documento-no-memo" tabindex="-1">Inserir trecho do documento no memo <a class="header-anchor" href="#inserir-trecho-do-documento-no-memo" aria-label="Permalink to &quot;Inserir trecho do documento no memo&quot;">​</a></h1><h2 id="o-que-faz" tabindex="-1">O que faz <a class="header-anchor" href="#o-que-faz" aria-label="Permalink to &quot;O que faz&quot;">​</a></h2><p>Com um documento aberto, você seleciona uma frase (por exemplo, &quot;Intimei Fulana de Tal&quot; numa certidão de cumprimento de mandado) e a manda para o memo desse documento pelo botão direito. Não é preciso copiar, voltar à página do processo e colar. O memo aparece abaixo do nome do documento na tabela de eventos.</p><h2 id="onde-aparece" tabindex="-1">Onde aparece <a class="header-anchor" href="#onde-aparece" aria-label="Permalink to &quot;Onde aparece&quot;">​</a></h2><p><strong>eproc</strong>, no documento aberto a partir da tabela de eventos, no menu do botão direito sobre um trecho selecionado.</p><h2 id="passo-a-passo" tabindex="-1">Passo a passo <a class="header-anchor" href="#passo-a-passo" aria-label="Permalink to &quot;Passo a passo&quot;">​</a></h2><ol><li>Na página do processo, abra o documento clicando nele na tabela de eventos.</li><li>Selecione o trecho que deve ir para o memo.</li><li>Clique com o botão direito sobre a seleção e escolha <strong>Inserir trecho no memo</strong>.</li><li>Revise o texto no diálogo. Se o documento já tiver memo, o trecho aparece depois dele, numa linha nova. Dá para editar à vontade.</li><li>Clique em <strong>Salvar memo</strong>. Um aviso no canto confirma a gravação, e a tabela de eventos da página do processo já mostra o memo novo, como quando ele é editado por lá.</li></ol><h2 id="configuracoes-e-opcoes" tabindex="-1">Configurações e opções <a class="header-anchor" href="#configuracoes-e-opcoes" aria-label="Permalink to &quot;Configurações e opções&quot;">​</a></h2><p>Não há opções além de ligar e desligar.</p><h2 id="observacoes" tabindex="-1">Observações <a class="header-anchor" href="#observacoes" aria-label="Permalink to &quot;Observações&quot;">​</a></h2><ul><li>O memo é visível a todos os usuários que acessam o processo. O diálogo lembra isso antes de salvar.</li><li>O item só funciona com a página do processo aberta, na janela que abriu o documento: é dela que a extensão tira o caminho para o memo. Se ela foi fechada ou recarregada noutro processo, o item aparece desativado. Na pré-visualização do documento, dentro da própria página do processo, ele funciona normalmente; na aba aberta pelo botão &quot;Abrir documento em nova aba&quot; da pré-visualização, não, porque o eproc a abre sem ligação com a página do processo.</li><li>Shift + botão direito abre o menu normal do navegador.</li><li>Em documentos em PDF a seleção acontece no visualizador do navegador, onde a extensão não chega.</li></ul>',11)]))}const h=e(t,[["render",i]]);export{u as __pageData,h as default};
